/*
	VIOC_town_cleanup.sqf - agregado por tools/vio_build.py (copia configurada, no es del autor de la mision).
	Parche "town_cleanup" (2026-10-18). Se compila en todas las maquinas desde init.sqf (marcadores y avisos en el cliente);
	el seguimiento corre solo en el servidor (en la partida LAN el anfitrion es el servidor y la consola LOCAL EXEC llega aqui).
	Sirve para las misiones A y B y para cualquier mapa y bando.

	Problema: despues de tomar un pueblo quedan rezagados del duenio anterior dentro del area (el HUD de captura dice
	"<pueblo>: SV/maxSV (Enemys N)", Client\FSM\title_capture.fsm: Man/Car/Motorcycle/Tank/Air/Ship de los otros bandos a
	cti_town_range, por countSide). Mientras siguen ahi: la base avanzada no vende ni deja reaparecer (forward_bases,
	"Hay enemigos a menos de 300 m"), un campamento puede volver al enemigo (town_camp.fsm) y entonces no se compra
	infanteria en el pueblo, el pueblo no recupera SV y su FSM de ocupacion/resistencia sigue activa. Los grupos de la
	guarnicion del duenio anterior siguen con su town_patrol.fsm, que con el pueblo ajeno los manda al centro ("defense").

	Parametros de lobby:
	  VIOC_TOWN_CLEANUP       0 = no, 1 = si (por defecto).
	  VIOC_TOWN_CLEANUP_TIME  4 / 6 (por defecto) / 10: minutos tras la captura hasta borrar o rendir a los que no se fueron.

	Que hace (gancho en Server\Functions\Server_OnTownCaptured.sqf; el bucle del servidor revisa cada VIOC_TCL_TICK s):
	  Rezagados = IA viva, no jugador, no cautiva, de un bando enemigo del nuevo duenio, a menos de cti_town_range (550 m si
	  falta) del centro, que sea:
	    - del duenio anterior (cti_town_lastSideID): restos de la guarnicion o milicia de BECTI (Server_SpawnTownOccupation /
	      Server_SpawnTownResistance: grupos sin variables, con town_patrol.fsm), tiradores de estaticas del pueblo (equipo
	      CTI_<lado>_DefenseTeam, defensas reactivas de fortifications) y cualquier IA suelta de ese bando; o
	    - IA suelta de otro bando enemigo sin orden de ningun sistema cuyo pueblo mas cercano es este;
	    - en la capital tomada (VIOC_CR_CAP), tambien los refuerzos de capital_reinforce del duenio anterior (vioc_cr).
	  De que pueblo es: la guarnicion lleva vioc_tac_town (town_patrol.fsm, gancho de ai_tactics) y las estaticas de BECTI estan
	  en CTI_town_defenses de su pueblo; la de un pueblo vecino no cuenta (en Tanoa hay 22 pares a menos de 925 m), ni la IA sin
	  marca a menos de CTI_TOWNS_PATROL_RANGE + 100 m del centro de otro pueblo de su bando.
	  Nunca: jugadores ni grupos con un jugador; equipos IA de BECTI (cti_teams), el del comandante, el de defensa de la base,
	  obreros, recuperadores, el HQ, vehiculos especiales (cti_spec), estaticas de la base (cti_aman_enabled), grupos con
	  cti_funds (equipos IA); operaciones especiales (vioc_specops, vioc_so_*), mercenarios
	  (vioc_merc*), guerra irregular (vioc_iw_*: durmientes, emboscadas, coche bomba, cazas), asalto aereo (vioc_aa),
	  refuerzos de la capital fuera del caso anterior (vioc_cr*), ofensiva y guarnicion de la mision B (vioc_mb_wave, vioc_mb_guard), maniobras de
	  ai_tactics (vioc_tac_man, vioc_tac_busy), transportes de ai_transport (vioc_at_*), drones y su gente (unitIsUAV,
	  vioc_fpv*, vioc_uav), aeronaves y quien va dentro (incluidos aviones de airfields).
	  Fases (desde la captura):
	    - 60 s: retirada. Cada grupo rezagado recibe un punto de ruta MOVE (AWARE, YELLOW, FULL) al pueblo propio mas cercano
	      (de su bando, a menos de VIOC_TCL_DEST_MAX m, fuera del area, sin mas de VIOC_TCL_WATER_GAP m de agua seguida en
	      linea recta) o, si no hay, a un punto en tierra a 1,5-2 km del centro lejos del nuevo duenio. Los tiradores de
	      estaticas se bajan. Del equipo de estaticas de BECTI (un grupo por bando para todos los pueblos) solo los de este
	      pueblo pasan a un grupo nuevo. El grupo queda con vioc_tac_busy (el gancho de ai_tactics en town_patrol.fsm no le
	      da mas ordenes; sin ai_tactics se repite la orden si otro se la cambia) y cada hombre y su vehiculo con vioc_tcl = 1
	      (publico: lo lee forward_bases). Los que ya salieron (a VIOC_TCL_GONE_R m del area) y llegaron o llevan
	      VIOC_TCL_GONE_T s se borran cuando ningun jugador esta a VIOC_TCL_GONE_FREE m ni los ve: se reincorporan a su
	      bando sin quedar como IA huerfana.
	    - 3 min: los que siguen dentro aparecen en el mapa del nuevo duenio (Oeste/Este; marcadores locales, celdas de 50 m:
	      "Rezagados enemigos (N)"), que se actualizan y se borran solos. Aviso: "Quedan N enemigos en X; marcados en el mapa".
	    - VIOC_TOWN_CLEANUP_TIME min (6): cada VIOC_TCL_RETRY s, cada rezagado que sigue dentro (a pie, en un vehiculo o en una
	      estatica) se borra si ningun jugador (de cualquier bando) esta a menos de VIOC_TCL_NEAR m ni lo ve (checkVisibility a
	      VIOC_TCL_LOS m desde sus ojos; a VIOC_TCL_LOS_REMOTE m desde una aeronave en la que va, desde el dron conectado a su
	      terminal o, en el anfitrion, desde su camara); un vehiculo del pueblo que queda vacio se borra con el. Si hay un jugador a menos de 150 m pero nadie
	      lo ve en VIOC_TCL_HID_N revisiones seguidas, se rinde (como en la campana de Arma 3: setCaptive, sin armas, manos en
	      la nuca, quieto); un cautivo es civil para countSide, asi que deja de contar en el HUD, los campamentos, la captura y
	      la base avanzada, y se borra cuando nadie lo ve de cerca. Si un jugador lo ve, se espera.
	    - Cuando ya no queda ninguno: aviso "X despejado" y los campamentos del pueblo que volvieron al enemigo despues de la
	      captura (cti_camp_lastSideID = nuevo duenio) vuelven al duenio si no hay enemigos a VIOC_TCL_CAMP_R m (como
	      Server_OnTownCaptured.sqf: variables, bandera y Client_OnCampCaptured).
	    - Fin del seguimiento al despejar y borrar a los que se fueron, o a los VIOC_TCL_END s si ya no queda nadie dentro (con
	      rezagados dentro se sigue reintentando): los que nadie ve se borran; los demas (y los rendidos que alguien ve) pasan a
	      VIOC_TCL_LEFT (tope VIOC_TCL_LEFT_MAX) y se borran cuando nadie los vea (revision cada VIOC_TCL_RETRY s). Si el pueblo cambia de duenio, los grupos se sueltan (sin
	      vioc_tac_busy ni vioc_tcl: vuelven a su patrulla).
	  Base avanzada (gancho en VIOC_FB_fnc_safe): un rezagado con orden de retirada (vioc_tcl) solo cuenta a menos de
	  VIOC_TCL_FB_NEAR m (150) del ayudante; el radio VIOC_FB_SAFE_RADIUS (300 m) sigue igual para el resto.
	  Topes: VIOC_TCL_MAX_REC pueblos a la vez, VIOC_TCL_MAX_UNITS rezagados por pueblo, VIOC_TCL_MAX_GROUPS grupos en
	  retirada por pueblo, VIOC_TCL_MK_MAX marcadores por pueblo. No crea IA (salvo la prueba de consola, con la reserva
	  de perf_cleanup) y no guarda nada (variables solo en unidades y grupos, que BECTI no guarda).
	Consola (LOCAL EXEC en el anfitrion):
	  hint (call VIOC_TCL_fnc_info);              estado: pueblos seguidos, fase, rezagados, grupos en retirada, cuentas
	  hint (call VIOC_TCL_fnc_why);               pueblo mas cercano: cada enemigo que cuenta el HUD y por que es (o no) rezagado
	  hint ([6, true] call VIOC_TCL_fnc_simulate); 6 rezagados "atascados" (sin moverse) del duenio anterior en edificios del
	                                              pueblo propio mas cercano (2 km) y seguimiento rapido: retirada a los 15 s,
	                                              marcadores a los 45 s, limpieza desde los 90 s. [6, false]: se pueden ir.
	  call VIOC_TCL_fnc_now;                      los pueblos seguidos pasan ya a la fase de limpieza
*/
if (!isNil "VIOC_TCL_LOADED") exitWith {};
VIOC_TCL_LOADED = true;

//--- Ajustes
VIOC_TCL_TICK = 10;               // s por pasada del bucle del servidor
VIOC_TCL_T1 = 60;                 // s tras la captura: orden de retirada
VIOC_TCL_T2 = 180;                // s: marcadores y aviso
VIOC_TCL_RETRY = 30;              // s entre intentos de limpieza
VIOC_TCL_RANGE = 550;             // m si el pueblo no tiene cti_town_range
VIOC_TCL_NEAR = 150;              // m: un jugador tan cerca = combate cercano (no se borra)
VIOC_TCL_LOS = 1000;              // m: jugadores que podrian verlo (checkVisibility)
VIOC_TCL_LOS_REMOTE = 4000;       // m: desde una aeronave, un dron conectado o la camara del anfitrion
VIOC_TCL_HID_N = 2;               // revisiones seguidas con un jugador cerca y sin linea de vista para rendirse
VIOC_TCL_DEST_MAX = 5000;         // m: pueblo propio mas lejano al que se retiran
VIOC_TCL_OUT_R = [1750, 1500, 2000]; // m del centro: punto de retirada si no hay pueblo propio
VIOC_TCL_WATER_GAP = 250;         // m de agua seguida en linea recta que todavia se acepta (rios, puentes)
VIOC_TCL_GONE_R = 200;            // m fuera del area: ya se fueron
VIOC_TCL_GONE_T = 480;            // s tras la orden: los que ya salieron se borran aunque no hayan llegado
VIOC_TCL_GONE_FREE = 400;         // m sin jugadores para borrar a los que se fueron
VIOC_TCL_ARRIVE = 150;            // m del punto de retirada: llegaron
VIOC_TCL_STALL = 90;              // s sin acercarse 25 m al punto de retirada: se repite la orden (otro sistema se la cambio)
VIOC_TCL_MAX_REC = 8;             // pueblos seguidos a la vez
VIOC_TCL_MAX_UNITS = 60;          // rezagados por pueblo
VIOC_TCL_MAX_GROUPS = 24;         // grupos en retirada por pueblo
VIOC_TCL_MK_MAX = 10;             // marcadores por pueblo
VIOC_TCL_MK_GRID = 50;            // m: celda de los marcadores (posicion aproximada)
VIOC_TCL_MK_SIZE = 50;            // m: radio del marcador
VIOC_TCL_MK_RESEND = 60;          // s: se reenvian aunque no cambien (para quien entro despues)
VIOC_TCL_FB_NEAR = 150;           // m: rezagados en retirada que todavia cuentan para la base avanzada
VIOC_TCL_CAMP_R = 30;             // m sin enemigos para devolver un campamento
VIOC_TCL_LEFT_MAX = 200;          // rezagados que quedaron al cerrar un pueblo y se borran cuando nadie los ve
VIOC_TCL_SIM_MAX = 10;            // hombres como mucho en la prueba de consola
VIOC_TCL_SIM_RESERVE = 20;        // plazas del presupuesto de IA (perf_cleanup) que la prueba deja libres
//--- variables que sacan a un grupo, a una unidad o a su vehiculo de la limpieza (otros sistemas con ordenes propias)
VIOC_TCL_GVARS = ["cti_funds", "vioc_specops", "vioc_merc", "vioc_iw_hunt", "vioc_iw_amb", "vioc_iw_ambHit", "vioc_aa", "vioc_cr",
	"vioc_cr_role", "vioc_mb_wave", "vioc_mb_guard", "vioc_tac_man", "vioc_at_owner", "vioc_at_tv", "vioc_fpv_op", "vioc_fpv_u", "vioc_air_busy"];
VIOC_TCL_UVARS = ["vioc_merc", "vioc_merc_role", "vioc_merc_boss", "vioc_merc_post", "vioc_iw_kind", "vioc_iw_covert", "vioc_iw_revealed",
	"vioc_iw_side", "vioc_specops", "vioc_so_joined", "vioc_so_exfil", "vioc_so_preq", "vioc_fpv", "vioc_aa", "vioc_cr", "vioc_mb_wave",
	"vioc_fg_air", "vioc_at_ride", "vioc_at_crew"];
VIOC_TCL_VVARS = ["cti_spec", "vioc_aa", "vioc_specops", "vioc_merc", "vioc_cr", "vioc_mb_wave", "vioc_mb_guard", "vioc_iw_vbied", "vioc_iw_drv",
	"vioc_at_owner", "vioc_at_tg", "vioc_uav", "vioc_grg", "vioc_as_kind", "vioc_as_nosave", "VIOC_AF_parked", "VIOC_KEEP"];

//--- ---------------------------------- cliente ----------------------------------
//--- [texto]: aviso corto (llega con remoteExecCall al bando del nuevo duenio)
VIOC_TCL_fnc_note = {
	params [["_t", ""]];
	if (hasInterface && {_t isEqualType ""} && {_t != ""}) then {systemChat _t};
};

//--- [clave, [[posicion, hombres, color], ...], claves activas]: marcadores locales de un pueblo (lista vacia: se borran).
//--- Las claves que ya no estan activas se borran tambien (por si se perdio un aviso de borrado).
VIOC_TCL_fnc_mk = {
	params [["_key", ""], ["_list", []], ["_act", []]];
	if (!hasInterface || {!(_key isEqualType "")} || {_key == ""}) exitWith {};
	if (isNil "VIOC_TCL_CMK") then {VIOC_TCL_CMK = createHashMap};
	private _del = {
		params ["_k", "_from", "_to"];
		for "_i" from _from to (_to - 1) do {
			deleteMarkerLocal format ["VIOC_TCL_%1_%2a", _k, _i];
			deleteMarkerLocal format ["VIOC_TCL_%1_%2b", _k, _i];
		};
	};
	//--- claves viejas
	if (_act isEqualType []) then {
		{
			private _k = _x;
			if (!(_k in _act) && {!(_k isEqualTo _key)}) then {
				[_k, 0, VIOC_TCL_CMK getOrDefault [_k, 0]] call _del;
				VIOC_TCL_CMK deleteAt _k;
			};
		} forEach (keys VIOC_TCL_CMK);
	};
	private _old = VIOC_TCL_CMK getOrDefault [_key, 0];
	private _n = (count _list) min VIOC_TCL_MK_MAX;
	for "_i" from 0 to (_n - 1) do {
		(_list select _i) params [["_p", [0, 0, 0]], ["_cnt", 1], ["_col", "ColorRed"]];
		private _a = format ["VIOC_TCL_%1_%2a", _key, _i];
		private _b = format ["VIOC_TCL_%1_%2b", _key, _i];
		if (_i >= _old) then {
			createMarkerLocal [_a, _p];
			_a setMarkerShapeLocal "ELLIPSE";
			_a setMarkerBrushLocal "FDiagonal";
			_a setMarkerSizeLocal [VIOC_TCL_MK_SIZE, VIOC_TCL_MK_SIZE];
			_a setMarkerAlphaLocal 0.8;
			createMarkerLocal [_b, _p];
			_b setMarkerTypeLocal "mil_warning";
			_b setMarkerSizeLocal [0.7, 0.7];
		};
		_a setMarkerPosLocal _p;
		_a setMarkerColorLocal _col;
		_b setMarkerPosLocal _p;
		_b setMarkerColorLocal _col;
		_b setMarkerTextLocal format ["Rezagados enemigos (%1)", _cnt];
	};
	[_key, _n, _old] call _del;
	if (_n == 0) then {VIOC_TCL_CMK deleteAt _key} else {VIOC_TCL_CMK set [_key, _n]};
};

if (!isServer) exitWith {};

//--- ---------------------------------- servidor ----------------------------------
VIOC_TCL_ON = 1;
VIOC_TCL_T3 = 360;
VIOC_TCL_END = 1500;
VIOC_TCL_REC = [];                // pueblos seguidos (hashmaps)
VIOC_TCL_IDS = [];                // sus id
VIOC_TCL_PEND = [];               // capturas que llegaron por el gancho: [pueblo, nuevo, anterior, hora, rapido]
VIOC_TCL_NID = 0;
VIOC_TCL_LEFT = [];               // los que quedaron al cerrar un pueblo (rendidos, en retirada): se borran cuando nadie los ve
VIOC_TCL_LEFT_T = -1;
VIOC_TCL_RUNNING = false;
VIOC_TCL_INFO = [0, 0, 0, 0, 0, 0, 0]; // [pueblos seguidos, grupos con orden de retirada, retirados (borrados fuera), borrados dentro, rendidos, campamentos devueltos, avisos]

VIOC_TCL_fnc_log = {
	params ["_t"];
	diag_log format ["[VIOC town_cleanup] %1", _t];
};

VIOC_TCL_fnc_p0 = {
	private _p = if (_this isEqualType objNull) then {getPosATL _this} else {_this};
	[_p select 0, _p select 1, 0]
};

VIOC_TCL_fnc_tname = {
	params ["_t"];
	if (isNull _t) exitWith {"?"};
	_t getVariable ["cti_town_name", "?"]
};

VIOC_TCL_fnc_sideName = {
	params ["_s"];
	switch (_s) do {
		case west: {"Oeste"};
		case east: {"Este"};
		case resistance: {"guerrilla"};
		default {str _s};
	}
};

VIOC_TCL_fnc_color = {
	params ["_s"];
	switch (_s) do {
		case west: {"ColorWEST"};
		case east: {"ColorEAST"};
		case resistance: {"ColorGUER"};
		default {"ColorRed"};
	}
};

//--- Jugadores reales (sin clientes sin cabeza)
VIOC_TCL_fnc_players = {
	allPlayers select {alive _x && {!(_x isKindOf "HeadlessClient_F")}}
};

//--- [objeto (unidad o vehiculo), jugadores, radio] -> [algun jugador a menos del radio, algun jugador lo ve]
//--- "Lo ve": linea de vista (checkVisibility) desde sus ojos a VIOC_TCL_LOS m, o a VIOC_TCL_LOS_REMOTE m si va en una aeronave
//--- (Ghostrider: el cuerpo va en el puesto del artillero o en la carga); desde el dron que tenga conectado (terminal UAV); y,
//--- en el anfitrion con interfaz, desde su camara (positionCameraToWorld: camara propia del Ghostrider, dron, camara de BECTI).
VIOC_TCL_fnc_obs = {
	params ["_o", "_pl", ["_near", VIOC_TCL_NEAR]];
	private _tgt = if (_o isKindOf "Man") then {eyePos _o} else {(getPosASL _o) vectorAdd [0, 0, 1.5]};
	private _n = false;
	private _s = false;
	{
		private _d = _x distance2D _o;
		if (_d < _near) then {_n = true};
		if (!_s) then {
			private _ve = vehicle _x;
			private _far = [VIOC_TCL_LOS, VIOC_TCL_LOS_REMOTE] select (_ve isKindOf "Air");
			if (_d < _far && {([_ve, "VIEW", _o] checkVisibility [eyePos _x, _tgt]) > 0.2}) then {_s = true};
		};
		if (!_s) then {
			private _uav = getConnectedUAV _x;
			if (!isNull _uav && {(_uav distance2D _o) < VIOC_TCL_LOS_REMOTE} && {([_uav, "VIEW", _o] checkVisibility [getPosASL _uav, _tgt]) > 0.2}) then {_s = true};
		};
	} forEach _pl;
	if (!_s && {hasInterface}) then {
		private _cp = AGLToASL (positionCameraToWorld [0, 0, 0]);
		if ((_cp distance2D _o) < VIOC_TCL_LOS_REMOTE && {([cameraOn, "VIEW", _o] checkVisibility [_cp, _tgt]) > 0.2}) then {_s = true};
	};
	[_n, _s]
};

//--- [objetos, jugadores, radio] -> true si nadie esta a menos del radio de ninguno ni ve a ninguno
VIOC_TCL_fnc_unseenAll = {
	params ["_objs", "_pl", "_near"];
	private _ok = true;
	{
		private _ob = [_x, _pl, _near] call VIOC_TCL_fnc_obs;
		if ((_ob select 0) || {_ob select 1}) exitWith {_ok = false};
	} forEach _objs;
	_ok
};

//--- [desde, hasta] -> true si en linea recta no hay mas de VIOC_TCL_WATER_GAP m de agua seguida (muestra cada 50 m)
VIOC_TCL_fnc_dry = {
	params ["_a", "_b"];
	private _d = _a distance2D _b;
	private _n = ceil (_d / 50);
	private _step = _d / (_n max 1);
	private _run = 0;
	private _ok = true;
	for "_i" from 1 to (_n - 1) do {
		private _p = [(_a select 0) + ((_b select 0) - (_a select 0)) * _i / _n, (_a select 1) + ((_b select 1) - (_a select 1)) * _i / _n];
		_run = if (surfaceIsWater _p) then {_run + _step} else {0};
		if (_run > VIOC_TCL_WATER_GAP) exitWith {_ok = false};
	};
	_ok
};

//--- Grupos, unidades y vehiculos de BECTI que nunca se tocan: [grupos, unidades, vehiculos]
VIOC_TCL_fnc_excl = {
	private _gs = [];
	private _us = [];
	private _vs = [];
	{
		private _lg = (_x) call CTI_CO_FNC_GetSideLogic;
		if (!isNull _lg) then {
			{ if (!isNil "_x" && {_x isEqualType grpNull}) then {_gs pushBack _x} } forEach (_lg getVariable ["cti_teams", []]);
			_gs pushBack (_lg getVariable ["cti_commander_team", grpNull]);
			_gs pushBack (_lg getVariable ["cti_defensive_team", grpNull]);
			{ if (!isNil "_x" && {_x isEqualType objNull}) then {_us pushBack _x} } forEach (_lg getVariable ["cti_workers", []]);
			{ if (!isNil "_x" && {_x isEqualType objNull}) then {_vs pushBack _x} } forEach (_lg getVariable ["cti_salvagers", []]);
			_vs pushBack (_lg getVariable ["cti_hq", objNull]);
		};
	} forEach [west, east];
	[_gs - [grpNull], _us - [objNull], _vs - [objNull]]
};

//--- [estatica] -> pueblo de BECTI que la tiene en CTI_town_defenses (su "CTI_defense"), o objNull
VIOC_TCL_fnc_staticTown = {
	params ["_v"];
	private _res = objNull;
	{
		private _t = _x;
		if (((_t getVariable ["CTI_town_defenses", []]) findIf {(_x getVariable ["CTI_defense", objNull]) isEqualTo _v}) >= 0) exitWith {_res = _t};
	} forEach CTI_Towns;
	_res
};

//--- [unidad, pueblo seguido, exclusiones] -> "" si es un rezagado; si no, el motivo
VIOC_TCL_fnc_reason = {
	params ["_u", "_r", "_ex"];
	if (!alive _u) exitWith {"muerto"};
	if (isPlayer _u) exitWith {"jugador"};
	if (captive _u) exitWith {"cautivo o rendido"};
	private _g = group _u;
	if (isNull _g) exitWith {"sin grupo"};
	if !((side _g) in (_r get "foes")) exitWith {"no es enemigo del duenio"};
	if (_g in (_ex select 0)) exitWith {"escuadra IA, comandante o defensa de base de BECTI"};
	if (_u in (_ex select 1)) exitWith {"obrero de BECTI"};
	if (((units _g) findIf {isPlayer _x}) >= 0) exitWith {"grupo de un jugador"};
	private _claim = (_g getVariable ["vioc_tcl_g", []]) param [0, -1];
	if (_claim >= 0 && {_claim != (_r get "id")} && {_claim in VIOC_TCL_IDS}) exitWith {"lo sigue la limpieza de otro pueblo"};
	if (_claim < 0 && {_g getVariable ["vioc_tac_busy", false]}) exitWith {"maniobra de ai_tactics o caza de la guerra irregular"};
	//--- refuerzos de capital_reinforce (vioc_cr, cti_funds = 0) del duenio anterior en la capital tomada: son rezagados (al perderla
	//--- capital_reinforce solo los borra sin jugadores a 1 km, asi que con el jugador dentro no se iban nunca)
	private _crOld = (!isNil {_g getVariable "vioc_cr"}) && {((side _g) call CTI_CO_FNC_GetSideID) == (_r get "old")} && {(_r get "town") isEqualTo (missionNamespace getVariable ["VIOC_CR_CAP", objNull])};
	private _gv = VIOC_TCL_GVARS - (["cti_funds", "vioc_cr", "vioc_cr_role"] select {_crOld});
	private _uv = VIOC_TCL_UVARS - (["vioc_cr"] select {_crOld});
	private _i = _gv findIf {!isNil {_g getVariable _x}};
	if (_i >= 0) exitWith {format ["grupo con %1", _gv select _i]};
	_i = _uv findIf {!isNil {_u getVariable _x}};
	if (_i >= 0) exitWith {format ["unidad con %1", _uv select _i]};
	private _v = objectParent _u;
	if (!isNull _v) then {
		_i = VIOC_TCL_VVARS findIf {!isNil {_v getVariable _x}};
	};
	if (!isNull _v && {(_v isKindOf "Air") || {unitIsUAV _v}}) exitWith {"aeronave o dron"};
	if (!isNull _v && {_v in (_ex select 2)}) exitWith {"HQ o recuperador de BECTI"};
	if (!isNull _v && {!isNil {_v getVariable "cti_aman_enabled"}}) exitWith {"estatica de la base"};
	if (!isNull _v && {_i >= 0}) exitWith {format ["vehiculo con %1", VIOC_TCL_VVARS select _i]};
	//--- de que pueblo es: town_patrol.fsm marca su guarnicion con vioc_tac_town (gancho de ai_tactics); las estaticas de BECTI
	//--- estan en CTI_town_defenses de su pueblo. En Tanoa hay pueblos a menos de 925 m (550 + CTI_TOWNS_PATROL_RANGE): la
	//--- patrulla o los tiradores del vecino entran en el area y no son rezagados de este pueblo.
	private _town = _r get "town";
	private _gt = _g getVariable ["vioc_tac_town", objNull];
	if (!isNull _gt && {!(_gt isEqualTo _town)}) exitWith {"guarnicion de otro pueblo"};
	private _st = if (!isNull _v && {_v isKindOf "StaticWeapon"}) then {[_v] call VIOC_TCL_fnc_staticTown} else {objNull};
	private _myStatic = _st isEqualTo _town;
	if (!isNull _st && {!_myStatic}) exitWith {"estatica de otro pueblo"};
	private _ours = (_gt isEqualTo _town) || {_myStatic} || {_crOld} || {_claim == (_r get "id")}; //--- de este pueblo (o ya con la orden de este pueblo)
	//--- sin marca de este pueblo: si esta a menos de CTI_TOWNS_PATROL_RANGE + 100 m del centro de otro pueblo de su bando, es de ese pueblo
	private _sid = (side _g) call CTI_CO_FNC_GetSideID;
	private _nb = false;
	if (!_ours) then {
		private _pr = (missionNamespace getVariable ["CTI_TOWNS_PATROL_RANGE", 375]) + 100;
		_nb = (CTI_Towns findIf {!(_x isEqualTo _town) && {(_x getVariable ["cti_town_sideID", -1]) == _sid} && {(_x distance2D _u) < _pr}}) >= 0;
	};
	if (_nb) exitWith {"IA de un pueblo vecino de su bando"};
	if (_sid == (_r get "old")) exitWith {""};
	//--- tercer bando: solo la guarnicion marcada de este pueblo o IA suelta cuyo pueblo mas cercano es este
	if (!_ours && {!((_u call CTI_CO_FNC_GetClosestTown) isEqualTo _town)}) exitWith {"IA de otro pueblo"};
	""
};

//--- [pueblo seguido, exclusiones] -> rezagados dentro del area (VIOC_TCL_MAX_UNITS como mucho)
VIOC_TCL_fnc_scan = {
	params ["_r", "_ex"];
	private _res = [];
	{
		private _men = if (_x isKindOf "Man") then {[_x]} else {crew _x};
		{
			if ((count _res) < VIOC_TCL_MAX_UNITS && {([_x, _r, _ex] call VIOC_TCL_fnc_reason) isEqualTo ""}) then {_res pushBackUnique _x};
		} forEach _men;
	} forEach ((_r get "town") nearEntities [["Man", "Car", "Motorcycle", "Tank", "Ship", "StaticWeapon"], _r get "r"]);
	_res
};

//--- [grupo, pueblo seguido] -> [posicion, "pueblo" o "afuera"] o []
VIOC_TCL_fnc_dest = {
	params ["_g", "_r"];
	private _v = vehicle (leader _g);
	if (_v isKindOf "Ship") exitWith {[]};
	private _from = _v call VIOC_TCL_fnc_p0;
	private _town = _r get "town";
	private _c = _town call VIOC_TCL_fnc_p0;
	private _R = _r get "r";
	private _sid = (side _g) call CTI_CO_FNC_GetSideID;
	private _keys = [];
	{
		if (((_x getVariable ["cti_town_sideID", -1]) == _sid) && {!(_x isEqualTo _town)}) then {
			private _d = _x distance2D _from;
			if (_d < VIOC_TCL_DEST_MAX && {(_x distance2D _c) > (_R + 250)}) then {_keys pushBack [_d, _forEachIndex]};
		};
	} forEach CTI_Towns;
	_keys sort true;
	private _res = [];
	{
		private _p = (CTI_Towns select (_x select 1)) call VIOC_TCL_fnc_p0;
		if ([_from, _p] call VIOC_TCL_fnc_dry) exitWith {_res = _p};
	} forEach (_keys select [0, 4]);
	if (count _res > 1) exitWith {[_res, "pueblo"]};
	//--- sin pueblo propio a mano: un punto en tierra a 1,5-2 km del centro, del lado contrario al pueblo mas cercano del nuevo duenio
	private _new = _r get "new";
	private _ntw = CTI_Towns select {((_x getVariable ["cti_town_sideID", -1]) == _new) && {!(_x isEqualTo _town)}};
	private _away = random 360;
	private _nd = 1e9;
	{ if ((_x distance2D _c) < _nd) then {_nd = _x distance2D _c; _away = _x getDir _c} } forEach _ntw;
	private _foe = (call VIOC_TCL_fnc_players) select {(side group _x) isEqualTo (_r get "side")};
	private _ws = worldSize;
	{
		private _b = _away + _x;
		{
			private _p = _c getPos [_x, _b];
			if (!(surfaceIsWater _p) && {(_p select 0) > 100} && {(_p select 1) > 100} && {(_p select 0) < (_ws - 100)} && {(_p select 1) < (_ws - 100)}
				&& {(_ntw findIf {(_x distance2D _p) < 400}) < 0} && {(_foe findIf {(_x distance2D _p) < 400}) < 0} && {[_from, _p] call VIOC_TCL_fnc_dry}) exitWith {
				_res = [_p select 0, _p select 1, 0];
			};
		} forEach VIOC_TCL_OUT_R;
		if (count _res > 1) exitWith {};
	} forEach [0, 30, -30, 60, -60, 90, -90, 120, -120, 150, -150, 180];
	if (count _res > 1) exitWith {[_res, "afuera"]};
	[]
};

VIOC_TCL_fnc_clearWp = {
	params ["_g"];
	for "_i" from ((count (waypoints _g)) - 1) to 0 step -1 do {deleteWaypoint [_g, _i]};
};

//--- [grupo, destino]: punto de ruta de retirada
VIOC_TCL_fnc_move = {
	params ["_g", "_dest"];
	if (isNull _g || {!local _g} || {count _dest < 2}) exitWith {};
	[_g] call VIOC_TCL_fnc_clearWp;
	_g setBehaviour "AWARE";
	_g setCombatMode "YELLOW";
	_g setSpeedMode "FULL";
	_g setVariable ["vioc_tcl_pg", [time, (vehicle (leader _g)) distance2D _dest]]; //--- avance hacia el punto (VIOC_TCL_fnc_gone)
	private _w = _g addWaypoint [_dest, 0];
	_w setWaypointType "MOVE";
	_w setWaypointCompletionRadius 40;
	_g setCurrentWaypoint _w;
	private _l = leader _g;
	{ if (alive _x && {!isPlayer _x} && {!(_x isEqualTo _l)} && {isNull objectParent _x}) then {_x doFollow _l} } forEach (units _g);
};

//--- [unidad]: se baja de la estatica
VIOC_TCL_fnc_dismount = {
	params ["_u"];
	private _v = objectParent _u;
	if (isNull _v || {!(_v isKindOf "StaticWeapon")} || {!local _u}) exitWith {};
	[_u] orderGetIn false;
	unassignVehicle _u;
	doGetOut _u;
};

//--- [grupo, pueblo seguido, rezagados dentro]: orden de retirada (60 s)
VIOC_TCL_fnc_order = {
	params ["_g", "_r", "_in"];
	if (isNull _g) exitWith {};
	if (count (_r get "groups") >= VIOC_TCL_MAX_GROUPS) exitWith {};
	private _side = side _g;
	private _alive = (units _g) select {alive _x};
	private _mine = _alive select {_x in _in};
	//--- equipo de estaticas de BECTI (un grupo por bando para las estaticas de todos los pueblos) o grupo con la mayoria fuera del
	//--- pueblo: solo los de este pueblo pasan a un grupo nuevo; si no se puede (no es local o no hay grupo), quedan para la limpieza
	if ((_g isEqualTo (missionNamespace getVariable [format ["CTI_%1_DefenseTeam", _side], grpNull])) || {((count _mine) * 2) < (count _alive)}) then {
		private _ng = if (local _g && {count _mine > 0}) then {createGroup [_side, true]} else {grpNull};
		if (isNull _ng) then {
			_g = grpNull;
		} else {
			{ [_x] call VIOC_TCL_fnc_dismount } forEach _mine;
			_mine joinSilent _ng;
			_g = _ng;
		};
	};
	if (isNull _g) exitWith {};
	{ [_x] call VIOC_TCL_fnc_dismount } forEach ((units _g) select {alive _x});
	private _d = [_g, _r] call VIOC_TCL_fnc_dest;
	private _dest = _d param [0, []];
	_g setVariable ["vioc_tcl_g", [_r get "id", _dest, time]];
	_g setVariable ["vioc_tac_busy", true]; //--- gancho de ai_tactics en town_patrol.fsm: la patrulla del pueblo no lo devuelve al centro
	{
		if (alive _x) then {
			_x setVariable ["vioc_tcl", 1, true];
			private _v = objectParent _x;
			if (!isNull _v && {!(_v isKindOf "StaticWeapon")}) then {_v setVariable ["vioc_tcl", 1, true]};
		};
	} forEach (units _g);
	if (count _dest > 1) then {[_g, _dest] call VIOC_TCL_fnc_move};
	(_r get "groups") pushBack _g;
	VIOC_TCL_INFO set [1, (VIOC_TCL_INFO select 1) + 1];
	[format ["%1: %2 (%3, %4 hombres) %5", [_r get "town"] call VIOC_TCL_fnc_tname, groupId _g, [_side] call VIOC_TCL_fnc_sideName, {alive _x} count (units _g),
		if (count _dest > 1) then {format ["se retira (%1) a %2 m", _d select 1, round ((vehicle (leader _g)) distance2D _dest)]} else {
			if (local _g) then {"sin lugar al que retirarse: queda para la limpieza"} else {"no es local del servidor: queda para la limpieza"}}]] call VIOC_TCL_fnc_log;
};

//--- [pueblo] -> vehiculos de la guarnicion o la milicia de BECTI
VIOC_TCL_fnc_townVeh = {
	params ["_t"];
	(_t getVariable ["cti_town_occupation_active_vehicles", []]) + (_t getVariable ["cti_town_resistance_active_vehicles", []])
};

//--- [unidades, vehiculo o objNull, vehiculos del pueblo]: borra a los hombres y, si quedo vacio y es del pueblo, el vehiculo
VIOC_TCL_fnc_kill = {
	params ["_men", "_v", "_tv"];
	private _gs = [];
	{
		if (!isNull _x && {!isPlayer _x}) then {
			_gs pushBackUnique (group _x);
			if (isNull objectParent _x) then {deleteVehicle _x} else {(objectParent _x) deleteVehicleCrew _x};
		};
	} forEach _men;
	if (!isNull _v && {alive _v} && {!(_v isKindOf "StaticWeapon")} && {_v in _tv} && {((crew _v) findIf {alive _x && {!(_x in _men)}}) < 0}) then {deleteVehicle _v};
	{ if (!isNull _x && {local _x} && {(count (units _x)) == 0}) then {deleteGroup _x} } forEach _gs;
	count _men
};

//--- [unidad, pueblo seguido] -> true si se rindio (a pie, local): como BIS_surrender de la campana (missions_f_epa, C_out2).
//--- Pasa a un grupo de rendidos del pueblo (uno por bando y pueblo seguido) para no frenar a su grupo.
VIOC_TCL_fnc_surrender = {
	params ["_u", "_r"];
	if (!alive _u || {captive _u} || {!local _u} || {!isNull objectParent _u}) exitWith {false};
	private _si = [west, east, resistance] find (side (group _u));
	if (_si >= 0) then {
		private _sg = (_r get "sg") select _si;
		if (isNull _sg) then {
			_sg = createGroup [side (group _u), true];
			(_r get "sg") set [_si, _sg];
		};
		if (!isNull _sg) then {[_u] joinSilent _sg};
	};
	{_u disableAI _x} forEach ["AUTOTARGET", "MOVE", "TARGET"];
	_u setCaptive true;
	removeAllWeapons _u;
	_u playMove "AmovPercMstpSsurWnonDnon";
	_u setVariable ["vioc_tcl", 2, true];
	[_u] spawn {
		params ["_s"];
		sleep 4;
		if (alive _s) then {_s disableAI "ANIM"};
	};
	true
};

//--- [lado, texto]: aviso a los jugadores de ese bando (Oeste/Este)
VIOC_TCL_fnc_say = {
	params ["_side", "_txt"];
	[format ["aviso (%1): %2", [_side] call VIOC_TCL_fnc_sideName, _txt]] call VIOC_TCL_fnc_log;
	if (_side in [west, east]) then {
		[_txt] remoteExecCall ["VIOC_TCL_fnc_note", _side];
		VIOC_TCL_INFO set [6, (VIOC_TCL_INFO select 6) + 1];
	};
};

//--- [pueblo seguido, lista]: manda los marcadores al bando del nuevo duenio si cambiaron (o cada VIOC_TCL_MK_RESEND s)
VIOC_TCL_fnc_send = {
	params ["_r", "_list"];
	private _side = _r get "side";
	if !(_side in [west, east]) exitWith {};
	if ((_list isEqualTo (_r get "mkLast")) && {time < (_r get "mkT")}) exitWith {};
	if ((count _list == 0) && {count (_r get "mkLast") == 0} && {!(_r get "mkSent")}) exitWith {};
	_r set ["mkLast", +_list];
	_r set ["mkT", time + VIOC_TCL_MK_RESEND];
	_r set ["mkSent", count _list > 0];
	private _act = (VIOC_TCL_REC select {((_x get "side") isEqualTo _side) && {!(_x get "done")}}) apply {str (_x get "id")};
	[str (_r get "id"), _list, _act] remoteExecCall ["VIOC_TCL_fnc_mk", _side];
};

//--- [pueblo seguido, rezagados dentro]: marcadores por celdas de VIOC_TCL_MK_GRID m
VIOC_TCL_fnc_marks = {
	params ["_r", "_in"];
	private _ks = [];
	private _es = [];
	{
		private _p = getPosATL (vehicle _x);
		private _kx = round ((_p select 0) / VIOC_TCL_MK_GRID);
		private _ky = round ((_p select 1) / VIOC_TCL_MK_GRID);
		private _k = format ["%1_%2", _kx, _ky];
		private _i = _ks find _k;
		if (_i < 0) then {
			_ks pushBack _k;
			_es pushBack [[_kx * VIOC_TCL_MK_GRID, _ky * VIOC_TCL_MK_GRID, 0], 1, [side (group _x)] call VIOC_TCL_fnc_color];
		} else {
			private _e = _es select _i;
			_e set [1, (_e select 1) + 1];
		};
	} forEach _in;
	private _ord = _es apply {[-(_x select 1), _x select 0]};
	_ord sort true;
	private _list = [];
	{
		private _p = _x select 1;
		private _j = _es findIf {(_x select 0) isEqualTo _p};
		if (_j >= 0) then {_list pushBack (_es select _j)};
	} forEach (_ord select [0, VIOC_TCL_MK_MAX]);
	[_r, _list] call VIOC_TCL_fnc_send;
};

//--- [pueblo seguido] -> campamentos devueltos al duenio (los que volvieron al enemigo despues de la captura)
VIOC_TCL_fnc_campsBack = {
	params ["_r"];
	private _town = _r get "town";
	private _sid = _r get "new";
	private _side = _r get "side";
	if ((_town getVariable ["cti_town_sideID", -1]) != _sid) exitWith {0};
	private _n = 0;
	{
		private _cs = _x getVariable ["cti_camp_sideID", -1];
		if (_cs != _sid && {(_x getVariable ["cti_camp_lastSideID", -1]) == _sid}) then {
			private _near = (_x nearEntities ["Man", VIOC_TCL_CAMP_R]) select {alive _x};
			if (([_near, _side] call CTI_CO_FNC_GetAreaEnemiesCount) == 0) then {
				_x setVariable ["cti_camp_sideID", _sid, true];
				_x setVariable ["cti_camp_lastSideID", _cs, true];
				private _flag = _x getVariable ["CTI_flag", objNull];
				private _tex = missionNamespace getVariable [format ["CTI_%1FLAG", _side], ""];
				if (!isNull _flag && {_tex isEqualType ""} && {_tex != ""}) then {_flag setFlagTexture _tex};
				["CLIENT", "Client_OnCampCaptured", [_x, _sid, _cs]] call CTI_CO_FNC_NetSend;
				_n = _n + 1;
			};
		};
	} forEach (_town getVariable ["cti_town_camps", []]);
	if (_n > 0) then {
		VIOC_TCL_INFO set [5, (VIOC_TCL_INFO select 5) + _n];
		[format ["%1: %2 campamentos devueltos a %3", [_town] call VIOC_TCL_fnc_tname, _n, [_side] call VIOC_TCL_fnc_sideName]] call VIOC_TCL_fnc_log;
	};
	_n
};

//--- [pueblo seguido, jugadores, rezagados dentro]: grupos en retirada: repetir la orden si otro se la cambio; borrar a los que ya se fueron
VIOC_TCL_fnc_gone = {
	params ["_r", "_pl", "_in"];
	private _c = (_r get "town") call VIOC_TCL_fnc_p0;
	private _R = _r get "r";
	private _tv = [_r get "town"] call VIOC_TCL_fnc_townVeh;
	private _keep = [];
	{
		private _g = _x;
		private _alive = if (isNull _g) then {[]} else {(units _g) select {alive _x && {!isPlayer _x}}};
		if (count _alive > 0 && {((units _g) findIf {isPlayer _x}) < 0}) then {
			(_g getVariable ["vioc_tcl_g", []]) params ["", ["_dest", []], ["_tO", 0]];
			private _inside = _alive select {_x in _in};
			private _far = (_alive findIf {((vehicle _x) distance2D _c) < (_R + VIOC_TCL_GONE_R)}) < 0;
			private _arr = (count _dest > 1) && {((vehicle (leader _g)) distance2D _dest) < VIOC_TCL_ARRIVE};
			private _objs = [];
			{ _objs pushBackUnique (vehicle _x) } forEach _alive;
			if (count _inside == 0 && {_far} && {_arr || {(time - _tO) > (_r get "goneT")}} && {[_objs, _pl, VIOC_TCL_GONE_FREE] call VIOC_TCL_fnc_unseenAll}) then {
				private _n = 0;
				{
					private _v = _x;
					private _men = if (_v isKindOf "Man") then {[_v]} else {(crew _v) select {alive _x && {_x in _alive}}};
					_n = _n + ([_men, if (_v isKindOf "Man") then {objNull} else {_v}, _tv] call VIOC_TCL_fnc_kill);
				} forEach _objs;
				VIOC_TCL_INFO set [2, (VIOC_TCL_INFO select 2) + _n];
				(_r get "stats") set [0, ((_r get "stats") select 0) + _n];
				[format ["%1: %2 hombres que se retiraron %3 se reincorporan a su bando (borrados lejos de los jugadores)", [_r get "town"] call VIOC_TCL_fnc_tname, _n,
					["por tiempo", "al llegar"] select _arr]] call VIOC_TCL_fnc_log;
			} else {
				//--- todavia dentro o en camino: si otro sistema le cambio el punto de ruta, o no avanza en VIOC_TCL_STALL s, se repite la orden
				if (local _g && {count _dest > 1} && {!_arr} && {!_far}) then {
					private _cw = currentWaypoint _g;
					private _dd = (vehicle (leader _g)) distance2D _dest;
					(_g getVariable ["vioc_tcl_pg", [time, _dd]]) params ["_pt", "_pd"];
					private _again = (_cw >= (count (waypoints _g))) || {((waypointPosition [_g, _cw]) distance2D _dest) > 100};
					if (!_again && {(time - _pt) > VIOC_TCL_STALL}) then {
						_again = (_pd - _dd) < 25;
						_g setVariable ["vioc_tcl_pg", [time, _dd]];
					};
					if (_again) then {[_g, _dest] call VIOC_TCL_fnc_move};
				};
				_keep pushBack _g;
			};
		};
	} forEach (_r get "groups");
	_r set ["groups", _keep];
};

//--- [pueblo seguido, rezagados dentro, jugadores]: limpieza (desde VIOC_TCL_T3, cada VIOC_TCL_RETRY s)
VIOC_TCL_fnc_clean = {
	params ["_r", "_in", "_pl"];
	private _tv = [_r get "town"] call VIOC_TCL_fnc_townVeh;
	private _done = [];
	private _nDel = 0;
	private _nSur = 0;
	{
		private _u = _x;
		private _v = objectParent _u;
		private _o = if (isNull _v) then {_u} else {_v};
		if (alive _u && {!(_o in _done)}) then {
			_done pushBack _o;
			private _men = if (isNull _v) then {[_u]} else {(crew _v) select {alive _x}};
			//--- en un vehiculo: solo si todos los que van dentro son rezagados
			if ((_men findIf {!(_x in _in)}) < 0) then {
				private _ob = [_o, _pl] call VIOC_TCL_fnc_obs;
				if (!(_ob select 0) && {!(_ob select 1)}) then {
					_nDel = _nDel + ([_men, _v, _tv] call VIOC_TCL_fnc_kill);
				} else {
					if ((_ob select 0) && {!(_ob select 1)} && {isNull _v}) then {
						private _h = (_u getVariable ["vioc_tcl_hid", 0]) + 1;
						_u setVariable ["vioc_tcl_hid", _h];
						if (_h >= VIOC_TCL_HID_N && {count (_r get "surr") < VIOC_TCL_MAX_UNITS} && {[_u, _r] call VIOC_TCL_fnc_surrender}) then {
							(_r get "surr") pushBack _u;
							_nSur = _nSur + 1;
						};
					} else {
						_u setVariable ["vioc_tcl_hid", 0];
					};
				};
			};
		};
	} forEach _in;
	//--- rendidos: se borran cuando nadie esta cerca ni los ve
	private _keep = [];
	{
		if (!isNull _x && {alive _x}) then {
			private _ob = [_x, _pl] call VIOC_TCL_fnc_obs;
			if (!(_ob select 0) && {!(_ob select 1)}) then {_nDel = _nDel + ([[_x], objNull, _tv] call VIOC_TCL_fnc_kill)} else {_keep pushBack _x};
		};
	} forEach (_r get "surr");
	_r set ["surr", _keep];
	if (_nDel > 0 || {_nSur > 0}) then {
		VIOC_TCL_INFO set [3, (VIOC_TCL_INFO select 3) + _nDel];
		VIOC_TCL_INFO set [4, (VIOC_TCL_INFO select 4) + _nSur];
		(_r get "stats") set [1, ((_r get "stats") select 1) + _nDel];
		(_r get "stats") set [2, ((_r get "stats") select 2) + _nSur];
		[format ["%1: limpieza: %2 borrados (nadie cerca ni a la vista), %3 rendidos (un jugador cerca sin verlos)", [_r get "town"] call VIOC_TCL_fnc_tname, _nDel, _nSur]] call VIOC_TCL_fnc_log;
	};
};

//--- [pueblo seguido, motivo]: termina el seguimiento
VIOC_TCL_fnc_finish = {
	params ["_r", "_why"];
	if (_r get "done") exitWith {};
	_r set ["done", true];
	private _town = _r get "town";
	private _owned = !isNull _town && {(_town getVariable ["cti_town_sideID", -1]) == (_r get "new")};
	if (_r get "mkSent") then {[_r, []] call VIOC_TCL_fnc_send};
	if (_owned) then {
		//--- fin normal: los que nadie ve se borran; los demas se quedan donde estan (con vioc_tac_busy: la patrulla no los devuelve)
		private _pl = call VIOC_TCL_fnc_players;
		private _tv = [_town] call VIOC_TCL_fnc_townVeh;
		private _n = 0;
		private _objs = [];
		{ if (!isNull _x) then { { if (alive _x && {!isPlayer _x}) then {_objs pushBackUnique (vehicle _x)} } forEach (units _x) } } forEach (_r get "groups");
		{ if (!isNull _x && {alive _x}) then {_objs pushBackUnique _x} } forEach (_r get "surr");
		{
			private _o = _x;
			private _men = if (_o isKindOf "Man") then {[_o]} else {(crew _o) select {alive _x && {!isPlayer _x} && {((group _x) getVariable ["vioc_tcl_g", []]) param [0, -1] == (_r get "id")}}};
			if (([_o, _pl] call VIOC_TCL_fnc_obs) isEqualTo [false, false] && {(_o isKindOf "Man") || {count _men == ({alive _x} count (crew _o))}}) then {
				_n = _n + ([_men, if (_o isKindOf "Man") then {objNull} else {_o}, _tv] call VIOC_TCL_fnc_kill);
			} else {
				//--- alguien los ve: quedan en VIOC_TCL_LEFT y se borran cuando nadie los vea (no ocupan el presupuesto para siempre)
				{ if (count VIOC_TCL_LEFT < VIOC_TCL_LEFT_MAX) then {VIOC_TCL_LEFT pushBackUnique _x} } forEach _men;
			};
		} forEach _objs;
		if (_n > 0) then {VIOC_TCL_INFO set [3, (VIOC_TCL_INFO select 3) + _n]};
	} else {
		//--- el pueblo cambio de duenio: se sueltan (vuelven a su patrulla o a lo que les ordene la mision)
		{
			if (!isNull _x && {((_x getVariable ["vioc_tcl_g", []]) param [0, -1]) == (_r get "id")}) then {
				_x setVariable ["vioc_tac_busy", nil];
				_x setVariable ["vioc_tcl_g", nil];
				{ if (!isNull _x) then {_x setVariable ["vioc_tcl", nil, true]; private _v = objectParent _x; if (!isNull _v) then {_v setVariable ["vioc_tcl", nil, true]}} } forEach (units _x);
			};
		} forEach (_r get "groups");
	};
	(_r get "stats") params ["_a", "_b", "_s"];
	[format ["%1: fin del seguimiento (%2): %3 se fueron, %4 borrados dentro, %5 rendidos", [_town] call VIOC_TCL_fnc_tname, _why, _a, _b, _s]] call VIOC_TCL_fnc_log;
};

//--- [pueblo, nuevo duenio (ID), duenio anterior (ID), hora de la captura, rapido] -> pueblo seguido
VIOC_TCL_fnc_newRec = {
	params ["_town", "_new", "_old", ["_t0", time], ["_fast", false]];
	if (isNull _town) exitWith {};
	{ if ((_x get "town") isEqualTo _town) then {[_x, "nueva captura"] call VIOC_TCL_fnc_finish} } forEach VIOC_TCL_REC;
	VIOC_TCL_REC = VIOC_TCL_REC select {!(_x get "done")};
	while {count VIOC_TCL_REC >= VIOC_TCL_MAX_REC} do {
		[VIOC_TCL_REC select 0, "tope de pueblos seguidos"] call VIOC_TCL_fnc_finish;
		VIOC_TCL_REC deleteAt 0;
	};
	private _side = (_new) call CTI_CO_FNC_GetSideFromID;
	private _tm = if (_fast) then {[15, 45, 90, 15, 120, 600]} else {[VIOC_TCL_T1, VIOC_TCL_T2, VIOC_TCL_T3, VIOC_TCL_RETRY, VIOC_TCL_GONE_T, VIOC_TCL_END]};
	VIOC_TCL_NID = VIOC_TCL_NID + 1;
	private _r = createHashMapFromArray [["id", VIOC_TCL_NID], ["town", _town], ["new", _new], ["side", _side], ["old", _old],
		["foes", [west, east, resistance] - [_side]], ["t0", _t0], ["r", _town getVariable ["cti_town_range", VIOC_TCL_RANGE]], ["fast", _fast],
		["tm", _tm], ["goneT", _tm select 4], ["p1", false], ["seen", 0], ["in", 0], ["groups", []], ["surr", []], ["ann", false], ["clear", false],
		["next3", -1], ["mkLast", []], ["mkT", -1], ["mkSent", false], ["stats", [0, 0, 0]], ["sg", [grpNull, grpNull, grpNull]], ["done", false]];
	VIOC_TCL_REC pushBack _r;
	VIOC_TCL_IDS = VIOC_TCL_REC apply {_x get "id"};
	VIOC_TCL_INFO set [0, (VIOC_TCL_INFO select 0) + 1];
	[format ["%1: tomado por %2 (antes %3)%4; seguimiento %5", [_town] call VIOC_TCL_fnc_tname, [_side] call VIOC_TCL_fnc_sideName,
		[(_old) call CTI_CO_FNC_GetSideFromID] call VIOC_TCL_fnc_sideName, ["", " [prueba de consola]"] select _fast, VIOC_TCL_NID]] call VIOC_TCL_fnc_log;
	_r
};

//--- [pueblo seguido, exclusiones, jugadores]: una pasada
VIOC_TCL_fnc_recTick = {
	params ["_r", "_ex", "_pl"];
	private _town = _r get "town";
	if (isNull _town || {(_town getVariable ["cti_town_sideID", -1]) != (_r get "new")}) exitWith {[_r, "el pueblo cambio de duenio"] call VIOC_TCL_fnc_finish};
	(_r get "tm") params ["_t1", "_t2", "_t3", "_retry", "", "_end"];
	private _age = time - (_r get "t0");
	if (_age < _t1) exitWith {};
	private _name = [_town] call VIOC_TCL_fnc_tname;
	//--- 1) rezagados dentro (los de antes y los nuevos) y orden de retirada a los grupos nuevos
	private _in = [_r, _ex] call VIOC_TCL_fnc_scan;
	private _gs = [];
	{ _gs pushBackUnique (group _x) } forEach _in;
	{
		if ((((_x getVariable ["vioc_tcl_g", []]) param [0, -1]) != (_r get "id"))) then {[_x, _r, _in] call VIOC_TCL_fnc_order};
	} forEach _gs;
	if !(_r get "p1") then {
		_r set ["p1", true];
		_r set ["seen", count _in];
		[format ["%1: %2 rezagados en %3 grupos a %4 m", _name, count _in, count _gs, _r get "r"]] call VIOC_TCL_fnc_log;
	};
	//--- 2) los que se van
	[_r, _pl, _in] call VIOC_TCL_fnc_gone;
	//--- 3) limpieza
	if (_age >= _t3 && {time >= (_r get "next3")}) then {
		_r set ["next3", time + _retry];
		[_r, _in, _pl] call VIOC_TCL_fnc_clean;
		_in = _in select {alive _x && {!captive _x}};
	};
	_r set ["in", count _in];
	//--- 4) marcadores y avisos
	if (_age >= _t2) then {
		if (!(_r get "clear")) then {[_r, _in] call VIOC_TCL_fnc_marks};
		if (!(_r get "ann") && {!(_r get "clear")} && {count _in > 0}) then {
			_r set ["ann", true];
			[_r get "side", if (count _in == 1) then {format ["Queda 1 enemigo en %1; marcado en el mapa", _name]} else {format ["Quedan %1 enemigos en %2; marcados en el mapa", count _in, _name]}] call VIOC_TCL_fnc_say;
		};
		if (!(_r get "clear") && {count _in == 0} && {(_r get "ann") || {(_r get "seen") > 0}}) then {
			_r set ["clear", true];
			[_r, []] call VIOC_TCL_fnc_send;
			private _nc = [_r] call VIOC_TCL_fnc_campsBack;
			[_r get "side", if (_nc > 0) then {format ["%1 despejado (%2 campamentos recuperados)", _name, _nc]} else {format ["%1 despejado", _name]}] call VIOC_TCL_fnc_say;
		};
		//--- 5) fin: despejado (o sin rezagados desde el principio) y sin grupos en camino ni rendidos. Con rezagados dentro no hay
		//--- tiempo maximo (se reintenta cada VIOC_TCL_RETRY s mientras un jugador los vea); sin ellos, a los VIOC_TCL_END s se termina igual.
		if ((count _in == 0) && {count (_r get "surr") == 0} && {((_r get "clear") || {(_r get "seen") == 0}) && {count (_r get "groups") == 0} || {_age > _end}}) then {
			if ((_r get "seen") == 0 && {!(_r get "clear")}) then {[_r] call VIOC_TCL_fnc_campsBack};
			[_r, if (_age > _end) then {"tiempo maximo"} else {["sin rezagados", "despejado"] select (_r get "clear")}] call VIOC_TCL_fnc_finish;
		};
	};
};

//--- Los que quedaron al cerrar un pueblo (VIOC_TCL_LEFT): se borran cuando ningun jugador esta a VIOC_TCL_NEAR m ni los ve.
//--- Salen de la lista si mueren, si un jugador los toma en su grupo o si su grupo volvio a quedar libre (el pueblo cambio de duenio).
VIOC_TCL_fnc_leftTick = {
	private _pl = call VIOC_TCL_fnc_players;
	private _n = 0;
	VIOC_TCL_LEFT = VIOC_TCL_LEFT select {
		private _u = _x;
		private _g = group _u;
		if (isNull _u || {!alive _u} || {isPlayer _u} || {isNull _g} || {((units _g) findIf {isPlayer _x}) >= 0}
			|| {!(captive _u) && {!(_g getVariable ["vioc_tac_busy", false])}}) then {false} else {
			if (([vehicle _u, _pl] call VIOC_TCL_fnc_obs) isEqualTo [false, false]) then {
				if (isNull objectParent _u) then {deleteVehicle _u} else {(objectParent _u) deleteVehicleCrew _u};
				_n = _n + 1;
				false
			} else {true};
		};
	};
	if (_n > 0) then {
		VIOC_TCL_INFO set [3, (VIOC_TCL_INFO select 3) + _n];
		[format ["%1 que habian quedado (rendidos o en retirada) borrados lejos de los jugadores; quedan %2", _n, count VIOC_TCL_LEFT]] call VIOC_TCL_fnc_log;
	};
};

//--- Gancho de Server_OnTownCaptured.sqf: [pueblo, nuevo duenio (ID), duenio anterior (ID)] (no espera: el bucle lo toma en la proxima pasada)
VIOC_TCL_fnc_onCaptured = {
	params ["_town", "_new", "_old"];
	if (isNull _town || {(missionNamespace getVariable ["VIOC_TOWN_CLEANUP", 1]) isEqualTo 0}) exitWith {};
	if (!(_new isEqualType 0) || {!(_old isEqualType 0)} || {_old == _new}) exitWith {};
	VIOC_TCL_PEND pushBack [_town, _new, _old, time, false];
	if (count VIOC_TCL_PEND > 16) then {VIOC_TCL_PEND deleteAt 0};
};

VIOC_TCL_fnc_loop = {
	waitUntil {sleep 2; !isNil "CTI_InitTowns" && {!isNil "CTI_Init_Server"}};
	{
		_x params ["_var", "_def", "_ok"];
		private _v = missionNamespace getVariable [_var, _def];
		if !(_v isEqualType 0 && {_v in _ok}) then {_v = _def};
		missionNamespace setVariable [_var, _v];
	} forEach [["VIOC_TOWN_CLEANUP", 1, [0, 1]], ["VIOC_TOWN_CLEANUP_TIME", 6, [4, 6, 10]]];
	VIOC_TCL_ON = missionNamespace getVariable ["VIOC_TOWN_CLEANUP", 1];
	VIOC_TCL_T3 = 60 * (missionNamespace getVariable ["VIOC_TOWN_CLEANUP_TIME", 6]);
	VIOC_TCL_END = 1500 max (VIOC_TCL_T3 + 900);
	if (VIOC_TCL_ON <= 0) exitWith {VIOC_TCL_PEND = []; ["apagado en el lobby"] call VIOC_TCL_fnc_log};
	VIOC_TCL_RUNNING = true;
	[format ["activo en %1: retirada a los %2 s, marcadores a los %3 s, limpieza desde los %4 s cada %5 s, fin a los %6 s; ai_tactics %7, forward_bases %8",
		worldName, VIOC_TCL_T1, VIOC_TCL_T2, VIOC_TCL_T3, VIOC_TCL_RETRY, VIOC_TCL_END, !isNil "VIOC_TAC_RUNNING", !isNil "VIOC_FB_fnc_safe"]] call VIOC_TCL_fnc_log;
	while {!(missionNamespace getVariable ["CTI_GameOver", false])} do {
		sleep VIOC_TCL_TICK;
		private _p = [];
		isNil {_p = VIOC_TCL_PEND; VIOC_TCL_PEND = []};
		{ _x call VIOC_TCL_fnc_newRec } forEach _p;
		if (count VIOC_TCL_LEFT > 0 && {time >= VIOC_TCL_LEFT_T}) then {
			VIOC_TCL_LEFT_T = time + VIOC_TCL_RETRY;
			call VIOC_TCL_fnc_leftTick;
		};
		if (count VIOC_TCL_REC > 0) then {
			private _ex = call VIOC_TCL_fnc_excl;
			private _pl = call VIOC_TCL_fnc_players;
			{ if (!(_x get "done")) then {[_x, _ex, _pl] call VIOC_TCL_fnc_recTick} } forEach VIOC_TCL_REC;
			VIOC_TCL_REC = VIOC_TCL_REC select {!(_x get "done")};
			VIOC_TCL_IDS = VIOC_TCL_REC apply {_x get "id"};
		};
	};
	VIOC_TCL_RUNNING = false;
};

//--- ---------------------------------- consola ----------------------------------
VIOC_TCL_fnc_info = {
	private _nl = toString [10];
	private _t = format ["VIOC town_cleanup: %1; retirada %2 s, marcadores %3 s, limpieza %4 s (cada %5 s), fin %6 s. Pueblos seguidos: %7",
		["APAGADO (lobby) o todavia arrancando", "activo"] select VIOC_TCL_RUNNING, VIOC_TCL_T1, VIOC_TCL_T2, VIOC_TCL_T3, VIOC_TCL_RETRY, VIOC_TCL_END, count VIOC_TCL_REC];
	{
		private _r = _x;
		private _age = round (time - (_r get "t0"));
		(_r get "tm") params ["_t1", "_t2", "_t3"];
		private _ph = switch (true) do {
			case (_age < _t1): {"espera"};
			case (_age < _t2): {"retirada"};
			case (_age < _t3): {"marcados"};
			default {"limpieza"};
		};
		(_r get "stats") params ["_a", "_b", "_s"];
		_t = _t + _nl + format ["%1 (%2, antes %3)%4: hace %5 s, fase %6; rezagados dentro %7 (al principio %8); grupos en retirada %9; rendidos vivos %10; se fueron %11, borrados %12, rendidos %13%14%15",
			[_r get "town"] call VIOC_TCL_fnc_tname, [_r get "side"] call VIOC_TCL_fnc_sideName, [(_r get "old") call CTI_CO_FNC_GetSideFromID] call VIOC_TCL_fnc_sideName,
			["", " [prueba]"] select (_r get "fast"), _age, _ph, _r get "in", _r get "seen", count (_r get "groups"), count (_r get "surr"), _a, _b, _s,
			["", "; aviso dado"] select (_r get "ann"), ["", "; DESPEJADO"] select (_r get "clear")];
	} forEach VIOC_TCL_REC;
	_t = _t + _nl + format ["Total: %1 pueblos, %2 grupos con orden de retirada, %3 se fueron, %4 borrados dentro, %5 rendidos, %6 campamentos devueltos, %7 avisos; quedaron %8 por borrar cuando nadie los vea",
		VIOC_TCL_INFO select 0, VIOC_TCL_INFO select 1, VIOC_TCL_INFO select 2, VIOC_TCL_INFO select 3, VIOC_TCL_INFO select 4, VIOC_TCL_INFO select 5, VIOC_TCL_INFO select 6,
		{!isNull _x && {alive _x}} count VIOC_TCL_LEFT];
	_t
};

//--- Pueblo mas cercano al jugador: los enemigos que cuenta el HUD de captura y por que cada uno es (o no) rezagado
VIOC_TCL_fnc_why = {
	if (isNull player) exitWith {"VIOC town_cleanup: sin jugador local"};
	private _town = (getPosATL player) call CTI_CO_FNC_GetClosestTown;
	if (isNull _town) exitWith {"VIOC town_cleanup: sin pueblos"};
	private _sid = _town getVariable ["cti_town_sideID", -1];
	private _side = (_sid) call CTI_CO_FNC_GetSideFromID;
	private _ri = VIOC_TCL_REC findIf {(_x get "town") isEqualTo _town};
	private _r = if (_ri >= 0) then {VIOC_TCL_REC select _ri} else {
		createHashMapFromArray [["id", -1], ["town", _town], ["new", _sid], ["side", _side], ["old", _town getVariable ["cti_town_lastSideID", -1]],
			["foes", [west, east, resistance] - [_side]], ["r", _town getVariable ["cti_town_range", VIOC_TCL_RANGE]]]
	};
	private _ex = call VIOC_TCL_fnc_excl;
	private _hudObjs = (_town nearEntities [["Man", "Car", "Motorcycle", "Tank", "Air", "Ship"], _r get "r"]) unitsBelowHeight 40; //--- como title_capture.fsm
	private _hud = 0;
	{ _hud = _hud + (_x countSide _hudObjs) } forEach (_r get "foes");
	private _objs = (_town nearEntities [["Man", "Car", "Motorcycle", "Tank", "Air", "Ship", "StaticWeapon"], _r get "r"]) unitsBelowHeight 40;
	private _rs = [];
	private _ns = [];
	{
		private _men = if (_x isKindOf "Man") then {[_x]} else {crew _x};
		{
			if ((side (group _x)) in (_r get "foes")) then {
				private _w = [_x, _r, _ex] call VIOC_TCL_fnc_reason;
				if (_w isEqualTo "") then {_w = "REZAGADO"};
				private _i = _rs find _w;
				if (_i < 0) then {_rs pushBack _w; _ns pushBack 1} else {_ns set [_i, (_ns select _i) + 1]};
			};
		} forEach _men;
	} forEach _objs;
	private _nl = toString [10];
	private _t = format ["%1 (de %2, antes %3, %4 m): el HUD cuenta %5 enemigos (vehiculos tripulados como 1; las estaticas no).%6",
		[_town] call VIOC_TCL_fnc_tname, [_side] call VIOC_TCL_fnc_sideName, [(_r get "old") call CTI_CO_FNC_GetSideFromID] call VIOC_TCL_fnc_sideName,
		_r get "r", _hud, [" Sin seguimiento ahora.", " En seguimiento."] select (_ri >= 0)];
	{ _t = _t + _nl + format ["%1: %2", _x, _ns select _forEachIndex] } forEach _rs;
	_t
};

//--- [hombres, atascados]: prueba de consola en el pueblo propio mas cercano (2 km): rezagados del duenio anterior en edificios
VIOC_TCL_fnc_simulate = {
	params [["_n", 6], ["_stuck", true]];
	if (!isServer || {isNull player}) exitWith {"VIOC town_cleanup: la prueba corre en el anfitrion (LOCAL EXEC en la partida LAN)"};
	if (!VIOC_TCL_RUNNING) exitWith {"VIOC town_cleanup: apagado en el lobby o todavia arrancando"};
	_n = ((round _n) max 1) min VIOC_TCL_SIM_MAX;
	private _side = side (group player);
	private _sid = (_side) call CTI_CO_FNC_GetSideID;
	private _keys = [];
	{ if (((_x getVariable ["cti_town_sideID", -1]) == _sid) && {(_x distance2D player) < 2000}) then {_keys pushBack [_x distance2D player, _forEachIndex]} } forEach CTI_Towns;
	if (count _keys == 0) exitWith {"VIOC town_cleanup: no hay un pueblo de tu bando a menos de 2 km"};
	_keys sort true;
	private _town = CTI_Towns select ((_keys select 0) select 1);
	private _old = _town getVariable ["cti_town_lastSideID", -1];
	if (!(_old in [CTI_WEST_ID, CTI_EAST_ID, CTI_RESISTANCE_ID]) || {_old == _sid}) then {_old = [CTI_WEST_ID, CTI_EAST_ID] select (_sid == CTI_WEST_ID)};
	private _foe = (_old) call CTI_CO_FNC_GetSideFromID;
	private _cls = missionNamespace getVariable [format ["CTI_%1_Soldier", _foe], ""];
	if (_cls isEqualType []) then {_cls = _cls param [0, ""]};
	if !(_cls isEqualType "" && {isClass (configFile >> "CfgVehicles" >> _cls)}) then {_cls = missionNamespace getVariable [format ["CTI_%1_Static", _foe], ""]};
	if !(_cls isEqualType "" && {isClass (configFile >> "CfgVehicles" >> _cls)}) exitWith {format ["VIOC town_cleanup: sin clase de soldado para %1", _foe]};
	private _max = missionNamespace getVariable ["VIOC_PERF_AI_MAX", -1];
	private _cnt = missionNamespace getVariable ["VIOC_PERF_AI_COUNT", -1];
	if ((_max isEqualType 0) && {_max > 0} && {(_cnt isEqualType 0)} && {(_cnt + _n + VIOC_TCL_SIM_RESERVE) > _max}) exitWith {format ["VIOC town_cleanup: sin presupuesto de IA (%1 de %2)", _cnt, _max]};
	if ((_cnt isEqualType 0) && {_cnt >= 0}) then {missionNamespace setVariable ["VIOC_PERF_AI_COUNT", _cnt + _n]};
	[_town, _n, _stuck, _foe, _old, _cls, _sid] spawn {
		params ["_town", "_n", "_stuck", "_foe", "_old", "_cls", "_sid"];
		private _c = _town call VIOC_TCL_fnc_p0;
		private _pl = call VIOC_TCL_fnc_players;
		private _ps = [];
		{
			private _h = _x;
			if ((_h distance2D _c) > 100) then {
				{
					if ((count _ps) < _n && {(_pl findIf {(_x distance2D _h) < 60}) < 0}) then {_ps pushBack _x};
				} forEach ((_h buildingPos -1) select [0, 2]);
			};
		} forEach ((nearestObjects [_c, ["House"], 380]) select {alive _x});
		private _tries = 0;
		while {(count _ps) < _n && {_tries < 60}} do {
			_tries = _tries + 1;
			private _p = _c getPos [100 + random 250, random 360];
			if (!(surfaceIsWater _p) && {(_pl findIf {(_x distance2D _p) < 60}) < 0}) then {_ps pushBack [_p select 0, _p select 1, 0]};
		};
		private _g = createGroup [_foe, true];
		if (isNull _g) exitWith {systemChat "VIOC town_cleanup: no se pudo crear el grupo de prueba"};
		{
			private _u = [_cls, _g, _x, _old] call CTI_CO_FNC_CreateUnit;
			if (!isNil "_u" && {_u isEqualType objNull} && {!isNull _u}) then {
				_u setPosATL _x;
				if (_stuck) then {_u disableAI "PATH"};
			};
			sleep 0.1;
		} forEach _ps;
		_g setBehaviour "AWARE";
		_g setCombatMode "YELLOW";
		isNil {VIOC_TCL_PEND pushBack [_town, _sid, _old, time, true]};
		systemChat format ["VIOC town_cleanup: %1 rezagados de prueba (%2%3) en %4; retirada a los 15 s, marcadores a los 45 s, limpieza desde los 90 s",
			{alive _x} count (units _g), [_foe] call VIOC_TCL_fnc_sideName, ["", ", atascados"] select _stuck, [_town] call VIOC_TCL_fnc_tname];
	};
	format ["VIOC town_cleanup: creando %1 rezagados en %2...", _n, [_town] call VIOC_TCL_fnc_tname]
};

//--- Los pueblos seguidos pasan ya a la fase de limpieza (para probar sin esperar)
VIOC_TCL_fnc_now = {
	{
		private _r = _x;
		(_r get "tm") params ["", "", "_t3"];
		if ((time - (_r get "t0")) < _t3) then {_r set ["t0", time - _t3]};
		_r set ["next3", -1];
	} forEach VIOC_TCL_REC;
	format ["VIOC town_cleanup: %1 pueblos en fase de limpieza (proxima pasada en %2 s como mucho)", count VIOC_TCL_REC, VIOC_TCL_TICK]
};

[] spawn VIOC_TCL_fnc_loop;

